    /* Battery Sweep Information*/
        /* Command Data */
        float gAmpl_Batt = 0;
        float gOffset_Batt = 0;
        float gStart_Frq_Batt = 0;
        float gEnd_Frq_Batt = 0;
        float gDuration_Batt_Sec = 0;

        /* Computed Data */
