    {
        ActualOffTime = 0;
        VariableTime = VariableTime + 10;
        SysSetVariableInt("SpecialTest", "IgnOffTime", VariableTime);
        Write("New timer is %d", VariableTime);
        CancelTimer(Countdown_tmr);
