{
    /* Set voltage stimulation mode */
    sysvar::VTS::Torque1.SetStimulationMode(1);
    sysvar::VTS::Torque2.SetStimulationMode(1);
    sysvar::VTS::Position1.SetStimulationMode(1);
    sysvar::VTS::Position2.SetStimulationMode(1);
